import type { ReactNode, CSSProperties } from 'react'

import { ScrollArea, useScrollArea } from '@chakra-ui/react'
import type { ScrollAreaRootProps, ScrollAreaRootProviderProps, UseScrollAreaReturn } from '@chakra-ui/react'

/** @jsxImportSource @emotion/react */
import { css } from '@emotion/react'


export const MyScrollArea = {
  Normal : ScrollAreaNormal,
  Provider: ScrollAreaProvider
}


type NormalProp = ScrollAreaRootProps & {
  children: ReactNode;
  hiddenBar?: boolean;
  css?: CSSProperties;
}
function ScrollAreaNormal(prop: NormalProp) {
  const { children, hiddenBar = false, css, ...otherProp } = prop;

  // otherPropで指定された属性は、このComponentで指定する属性より優先度高とする（より右側で適用する(※)）
  // ※ 通常のHTMLタグであれば、右側の方が優先度低だが、JSXでのJS処理では右側が優先度高
  // また、<ScrollArea.Content>にwin-width: fit-contentのstyleがchakra-ui側で直指定されているようだったので、undefined指定を明示的にしてクリア
  return (
    <ScrollArea.Root variant='always' css={[styles.root, css].flat()} {...otherProp}>
      <ScrollArea.Viewport className='scroll-viewport'>
        <ScrollArea.Content className='scroll-content' paddingEnd={{ smDown: '0', sm: '3' }} style={{ minWidth: undefined }}>
          {children}
        </ScrollArea.Content>
      </ScrollArea.Viewport>
      <ScrollArea.Scrollbar className='scrollbar-area' visibility={hiddenBar? 'hidden' : undefined} />
    </ScrollArea.Root>
  )
}

export function useMyScrollArea() {
  return useScrollArea();
}

type ProviderProp = Omit<ScrollAreaRootProviderProps & {
  scrollArea: UseScrollAreaReturn
  children: ReactNode;
  css?: CSSProperties;
}, 'value'>
function ScrollAreaProvider(prop: ProviderProp) {
  const { scrollArea, children, css, ...otherProp } = prop;
  
  // value指定以外はNormalと一緒
  return(
    <ScrollArea.RootProvider value={scrollArea} variant='always' css={[styles.root, css].flat()} {...otherProp}>
      <ScrollArea.Viewport className='scroll-viewport'>
        <ScrollArea.Content className='scroll-content' w={{ smDown: '100%', sm: 'calc(100% - 8px)' }} paddingEnd={{ smDown: '0', sm: '3' }} style={{ minWidth: undefined }}>
          {children}
        </ScrollArea.Content>
      </ScrollArea.Viewport>
      <ScrollArea.Scrollbar className='scrollbar-area'>
        {/* class名=chakra-scroll-area__thumb、もしくはdata-scope等で判別しても良いが、ここでは明示的にclass名を付ける */}
        <ScrollArea.Thumb className='scroll-thumb' />
      </ScrollArea.Scrollbar>
    </ScrollArea.RootProvider>
  )
}



const styles = {
  root: css`
    //background: rgb(255 255 255);
    
    .scroll-viewport {
      mask-image: linear-gradient(#000, #000);
      &[data-overflow-y] {
        mask-image: linear-gradient(#000,#000,transparent 0,#000 var(--scroll-shadow-size),#000 calc(100% - var(--scroll-shadow-size)),transparent);
        &[data-at-top] {
          mask-image: linear-gradient(180deg,#000 calc(100% - var(--scroll-shadow-size)),transparent);
        }
        &[data-at-bottom] {
          mask-image: linear-gradient(0deg,#000 calc(100% - var(--scroll-shadow-size)),transparent);
        }
      }
      
      .scroll-content {
        display: flex;
        flex-direction: column;
        //width: 100%;
        //min-width: fit-content;
        /* rootとviewportがheight:100%で親の最大高を超さないようにし、contentはmin-height:fit-contentで子要素の高さに合わせて広がり、overflowでスクロール制御とする */
        min-height: fit-content;
        flex-grow: 1;
        flex-basis: 0;
      }
    }
    
    /* スクロールバー非表示の時は右paddingをなしにする */
    &:has(> .scrollbar-area:not([data-overflow-x], [data-overflow-y])) {
      
      > .scroll-viewport > .scroll-content {
        padding-inline-end: 0;
      }
    }
  `
}


